function press(el){ el.classList.add("press"); setTimeout(() => el.classList.remove("press"), 130); }
const toast = t => A().toast(t);
function stamp(big, small){ if (!SR) return; const e = document.createElement("div"); e.className = "stamp"; e.innerHTML = `${esc(big)}<small>${esc(small)}</small>`; SR.appendChild(e); blip(220); setTimeout(() => blip(165), 90); setTimeout(() => { e.style.transition = "opacity .5s"; e.style.opacity = "0"; setTimeout(() => e.remove(), 500); }, 1500); }
const cheer = () => T(["说出来了！", "就是这样！", "对方听懂了！"][Math.random() * 3 | 0], ["You said it!", "That's it!", "Understood!"][Math.random() * 3 | 0]);
function finish(n){ if (done.has(n)) return; done.add(n); drawStairs(); draw(); scrollDown();
  setTimeout(() => { const [z, e] = STAMPS[n - 1]; stamp(L() === "zh" ? z : e, T("第 " + n + " 级 · 成了", "Step " + n + " · done")); A().confetti();
    if (done.size === 5) setTimeout(() => stamp(T("五级都上来了", "All five steps"), T("同一道题，从一个词到一小段", "One question — from a word to a story")), 1700); }, 700); }

// —— 一行字 ——
function lineHTML(o, cls = "z", who){ if (o.ns) return lineHTML(Object.assign({}, o, {ns: 0}), cls, who) + `<span class="ns">${T("（没录到声音）", "(no recording)")}</span>`;
  if (o.h) return `<span class="mean">${T("（听到的）", "(heard)")}</span><span class="${cls}" data-say="${esc(strip(o.t))}" data-who="">${o.t}</span>`;
  if (o.o) return `<span class="${cls}" data-say="${esc(o.o)}" data-lang="${esc(o.ol || "")}">${esc(o.o)}</span><span class="mean">${esc(o.m)}</span><div class="tv"><small>${L() === "zh" ? T("中文怎么说 · 点着听", "In Chinese · tap to hear") : T("英语怎么说 · 点着听", "In English · tap to hear")}</small><span class="${cls}" data-say="${esc(strip(o.t))}" data-who="${who || ""}">${o.t}</span>${o.p ? `<span class="py">${esc(o.p)}</span>` : ""}</div>`;
  return `<span class="${cls}" data-say="${esc(strip(o.t))}" data-who="${who || ""}">${o.t}</span>${o.p ? `<span class="py">${esc(o.p)}</span>` : ""}${o.m ? `<span class="mean">${esc(o.m)}</span>` : ""}`; }
function msgHTML(m){
  if (m.wait) return `<div class="msg wait"><img class="av s" src="${face(m.who)}" alt=""> ${esc(T(P(m.who).nm + " 看到会回你", P(m.who).nm + " will reply when " + PR(m.who).S + " sees it"))}</div>`;
  if (m.typing) return `<div class="typing"><img class="av s" src="${face(m.who)}" alt=""><i></i><i></i><i></i></div>`;
  if (m.me) return `<div class="msg me"><div class="who"><b>${T("你", "You")}</b>${m.to ? ` → <b>${esc(P(m.to).nm)}</b>` : ""}${m.dest ? ` → <b>${esc(m.dest)}</b>` : ""} ✓</div>${m.pic || ""}${lineHTML(m.o, "z", "")}</div>`;
  return `<div class="msg them"><img class="av s" src="${face(m.who)}" alt=""><div style="min-width:0;flex:1"><div class="who"><b>${esc(P(m.who).nm)}</b> · ${esc(city(m.who))}</div>${m.also ? `<span class="recast">${PASTD() ? T(esc(P(m.who).nm) + " 那天也说了", esc(P(m.who).nm) + " said that day") : T(esc(P(m.who).nm) + " 今天也说了", esc(P(m.who).nm) + " said today")}</span><br>` : ""}${m.recast ? `<span class="recast">${T("你是说", "So you mean")}</span><br>` : ""}${lineHTML(m.o, "z", m.who)}${m.img ? `<div class="pic" style="background-image:url('${esc(IMG(m.img))}')"></div>` : ""}</div></div>`; }
function replyIn(arr, who, o, extra, then){ if (!o) { then && then(); return; } arr.push({typing: true, who}); draw(); setTimeout(() => { arr.pop(); arr.push(Object.assign({who, o}, extra || {})); draw(); blip(990); say(o.o || o.t, who, null, o.o ? o.ol : null); then && setTimeout(then, 500); }, 1000); }

// —— 麦克风：主程序的录音 + 听写（HVI.recStart）。点一下（停顿就自己停）或按住（松手停）——
const SRok = () => !!(window.SpeechRecognition || window.webkitSpeechRecognition) && !!(window.HVI && window.HVI.recStart) && !!(navigator.mediaDevices && navigator.mediaDevices.getUserMedia && window.MediaRecorder);
let REC = null, recId = null, capT = null, idleT = null, t0 = 0, NOSR = false, HOLD = false;
const MIC = {};   // id → {ok(听到的话, 录音)}
const micBtn = id => NOSR ? `<button class="mic" data-act="said" data-id="${id}"><span class="ic">🗣️</span><span>${T("我说出来了", "I said it")}</span></button>` : `<button class="mic" data-mic="${id}"><span class="ic">🎤</span><span class="l2">${T("点一下或按住说", "Tap or hold to speak")}</span><span class="bars"><i></i><i></i><i></i><i></i></span></button>`;
function micHTML(id, noEar){ return `<div class="row">${noEar ? "" : `<button class="ear" data-act="ear" data-id="${id}">🔊 ${T("听", "Listen")}</button>`}${micBtn(id)}</div><div class="live" id="lv_${id}">${NOSR && !/^(h|ow)/.test(id) ? esc(T("这台设备认不出字。大声说出来，再点「我说出来了」。", "This device can't pick up words. Say it out loud, then tap “I said it”.")) : ""}</div>`; }
// 对得上多少：学中文按汉字，学英语按词
const units = s => L() === "zh" ? [...String(s || "")].filter(c => /[\u3400-\u9fff]/.test(c)) : (String(s || "").toLowerCase().replace(/<[^>]+>/g, "").match(/[a-z']+/g) || []);
function match(want, heard){ const w = units(want), h = units(heard); if (!w.length) return 1; return w.filter(c => h.includes(c)).length / w.length; }
function micStart(id){ const btn = SR.querySelector(`[data-mic="${id}"]`), live = $("#lv_" + id); if (!btn || recId) return;
  if (!(window.SpeechRecognition || window.webkitSpeechRecognition)){ NOSR = true; draw(); return; }   // 这台设备真的不会认字：才给「我说出来了」
  if (!SRok()){ typeOffer(id, "nomic"); return; }
  hush(); try { window.PODCAST && window.PODCAST.pause && window.PODCAST.pause(); } catch(e){} recId = id; btn.classList.add("on"); blip(660); let got = "";
  live.innerHTML = `<b>${T("在听……说完会自己停", "Listening… stops by itself")}</b>`;
  const end = (kind, v) => { if (recId !== id) return; recId = null; REC = null; clearTimeout(capT); clearTimeout(idleT); btn.classList.remove("on"); const txt = String((v && v.text) || got || "").trim(); const lv = $("#lv_" + id);
    const enough = !MIC[id] || !MIC[id].want || match(MIC[id].want, txt) >= .5;   // 跟播客一样：对得上一半才算；对不上一半就说没听清，不接现成回话
    if (kind === "ok" && txt && enough){ if (lv) lv.innerHTML = `<span class="okl">✓ ${T("听到了：", "Heard: ")}</span>${esc(txt)}`; MIC[id] && MIC[id].ok(txt, v && v.blob ? v : null); }
    else if (kind === "nomic") typeOffer(id, "nomic");
    // 听到了字、只是对不上一半：只让你再说一遍；没听到声音：再试一次，或者改成打字（「我说出来了」只留给这台设备不会认字的时候）
    else if (lv && txt) lv.innerHTML = `<span class="okl" style="color:var(--soft)">${T("听到：", "Heard: ")}</span>${esc(txt)}<br>${T("没听清，再说一遍。", "Didn't quite catch that — say it once more.")}`;
    else typeOffer(id, "empty"); };
  window.HVI.recStart({lang: BCP(), onText: t => { if (recId !== id) return; got = t; live.innerHTML = `<b>${T("在听……", "Listening…")}</b> ${esc(t)}`; clearTimeout(idleT); if (!HOLD) idleT = setTimeout(micStop, 1500); },
    onDone: v => end("ok", v), onError: () => end("nomic")})
   .then(h => { if (!h){ end("nomic"); return; } if (recId !== id){ try { h.stop(); } catch(e){} return; } REC = h; capT = setTimeout(micStop, 9000); })
   .catch(() => end("nomic")); }
function micStop(){ clearTimeout(idleT); if (recId && REC){ try { REC.stop(); } catch(e){} } }
// 这台设备不会认字时点「我说出来了」：算说过，但你那条消息标「没录到声音」
let SAIDNS = false;
function saidBtn(id){ const live = $("#lv_" + id); if (live) live.innerHTML = `<span class="okl">✓ ${T("说出来了", "Said it")}</span> <span class="ns">${T("（没录到声音）", "(no recording)")}</span>`; SAIDNS = true; try { MIC[id] && MIC[id].ok(null, null); } finally { SAIDNS = false; } }
// 能认字、但没听到声音（或者用不了麦克风）：再试一次，或者改成打字；打出来的那句当作你自己写的话
function typeOffer(id, why){ const lv = $("#lv_" + id); if (!lv) return; blip(330);
  lv.innerHTML = `${why === "nomic" ? T("这里听不到你的声音。", "We can't hear your voice here.") : T("没听到声音，再试一次。", "No sound came through — try again.")} <button class="said" data-act="type" data-id="${id}">✍️ ${T("改成打字", "Type it instead")}</button>`; }
function typeBox(id){ const lv = $("#lv_" + id); if (!lv) return; lv.innerHTML = `<div class="ownb"><textarea id="ty_${id}" placeholder="${esc(L() === "zh" ? T("用中文打出来……", "Type it in Chinese…") : T("用英语打出来……", "Type it in English…"))}">${esc(MIC[id] && MIC[id].want ? strip(MIC[id].want) : "")}</textarea><div class="row"><button class="send" data-act="typesend" data-id="${id}">${T("送出", "Send")}</button></div></div>`; const ta = $("#ty_" + id); if (ta) ta.focus(); }
function typeSend(id){ const ta = $("#ty_" + id), txt = ta ? ta.value.trim() : ""; if (!txt){ toast(T("先打一句", "Type something first")); return; }
  const n = cur, s = S[n], who = whoOf(n); s.hth = s.hth || []; s.hth.push({me: true, o: {t: esc(txt), p: "", m: T("（你自己写的）", "(your own words)")}, to: who}, {wait: true, who}); gotIt(ta);
  API.said({t: txt, p: "", n, own: 1, to: who}, null); draw(); }
const normT = t => String(t).toLowerCase().replace(/<[^>]+>/g, "").replace(/[，。！？、「」“”—…\s,.!?'’"-]/g, "");
// 麦克风听到什么就显示什么；听到的跟那句不一样，标「（听到的）」
function asHeard(o, heard){ if (heard == null && SAIDNS) return Object.assign({}, o, {ns: 1}); return heard && normT(heard) !== normT(o.t) ? {t: esc(heard), p: "", m: "", h: true} : o; }
function gotIt(el){ blip(1175); setTimeout(() => blip(1568), 90); flt(el, "✓"); toast(cheer()); }
// 说出来的这一句交给 howabout：下面出「送给世界 / 只留给自己」（听到的跟原句不一样，存听到的原话）
function give(n, o, heard, v){ const t = heard && normT(heard) !== normT(o.t) ? heard : strip(o.t); API.said({t, p: t === strip(o.t) ? (o.p || "") : "", n, heard: t !== strip(o.t) ? 1 : 0, nosnd: heard == null && SAIDNS ? 1 : 0}, v); }

// —— 台阶 ——
function drawStairs(){ const box = $("#stairs"); if (!box) return;
  box.innerHTML = STEPS.map((s, i) => { const n = i + 1; return `<button class="st${n === cur ? " on" : ""}${done.has(n) ? " done" : ""}" data-act="step" data-n="${n}" style="height:${58 + i * 11}px"><span class="n">${n}</span><span class="c">${esc(T(s[0], s[1]))}</span></button>`; }).join("");
  $("#sthint").innerHTML = (LAST > 1 ? T("停在你上次那一级", "Right where you left off") : T("你现在能做到哪一级，就点哪一级", "Pick the step you can do today")) + (cur < 5 && (LAST > 1 || done.size) ? ` · <button class="said" data-act="step" data-n="${cur + 1}" style="font-size:11.5px;color:var(--soft)">${T("再往上一级？", "One step up?")}</button>` : ""); }

// —— 第一级：一个词 ——
function s1(){ const s = S[1], d = D().s1, W = d.words || [], w = W.find(x => x.k === s.w), img = API.img();
  let h = `<div class="sh">${T("说一个词就行", "One word is enough")}</div><div class="ssub">${esc(d.sub ? T(d.sub.zh, d.sub.en) : T("拍一张，或者挑一个最像你的，再说一个词。", "Snap one, or pick the one most like yours — then say one word."))}</div>`;   // s1.sub / s1.snap：每天自己的说法（窗外题写「拍窗外」），没写用通用的
  const wins = W.filter(x => x.win);
  h += `<div class="wins"><button class="cam${s.ph === "own" ? " on" : ""}" data-act="cam">${img ? `<img src="${esc(img)}" alt="">` : `📷<br>${esc(d.snap ? T(d.snap.zh, d.snap.en) : T("拍一张", "Snap it"))}`}</button>` + wins.map(x => `<button class="win ${esc(x.win)}${s.ph === x.k ? " on" : ""}" data-act="ph" data-k="${esc(x.k)}" aria-label="${esc(x.m)}"><i></i></button>`).join("") + `</div>`;
  h += `<div class="lab">${T("一个词", "One word")}</div><div class="bigw">` + W.map(x => `<button class="bw${s.w === x.k ? " on" : ""}${s.ph === x.k && !s.w ? " hint" : ""}" data-act="w" data-k="${esc(x.k)}"><b>${esc(x.t)}</b><small>${esc(x.p || x.m)}</small>${x.p ? `<small>${esc(x.m)}</small>` : ""}</button>`).join("") + `</div>`;
  if (w){ const line = {t: w.t + (L() === "zh" ? "！" : "!"), p: w.p, m: w.m};
    MIC.s1 = {want: line.t, ok: (heard, v) => { if (s.said) return; s.said = true; s.heard = heard; gotIt($("#lv_s1")); give(1, line, heard, v); }};
    h += `<div class="say"><span class="z big" data-say="${esc(w.t)}" data-who="">${esc(line.t)}</span>${w.p ? `<span class="py">${esc(w.p)}</span>` : ""}<span class="mean">${esc(w.m)}</span>${s.said ? "" : micHTML("s1")}</div>`;
    if (s.said && !s.dest && !API.sent()) h += `<div class="ssub" style="margin-top:8px">↓ ${PASTD() ? T("送给世界，" + P(w.who).nm + " 会回你。一题送一条就好，也可以爬高一点再送。", "Send it to the world and " + P(w.who).nm + " will reply. One per question is plenty — or climb a little higher first, then send.") : T("送给世界，" + P(w.who).nm + " 会回你。今天送一条就好，也可以爬高一点再送。", "Send it to the world and " + P(w.who).nm + " will reply. One a day is plenty — or climb a little higher first, then send.")}</div>`; }
  if (s.th) h += `<div class="thread">${s.th.map(msgHTML).join("")}</div>`;
  if (w) h += help1(s, w);
  if (done.has(1) && s.said) h += nextBtn(2);
  return h; }
// 送出去的消息里只放你真拍的照片；挑的那扇窗只是你选的样子，不算照片
function picHTML(){ const img = API.img(); return img ? `<img class="mpic" src="${esc(img)}" alt="">` : ""; }
// howabout 送出去以后（第一级）：送给世界 → TA 回你；只留给自己 → 没人回这一条，下面照样看到 TA 今天自己说的
function sent1(world){ const s = S[1], w = (D().s1.words || []).find(x => x.k === s.w); if (!w || !s.said || s.dest) return; s.dest = world ? "world" : "me";
  const o = asHeard({t: w.t + (L() === "zh" ? "！" : "!"), p: w.p, m: w.m}, s.heard);
  s.th = [{me: true, o, pic: picHTML(), dest: world ? T("世界", "the world") : T("只有自己", "just me")}];
  if (world) replyIn(s.th, w.who, w.r, {img: w.img}, () => finish(1));
  else { blip(1046); s.th.push({who: w.who, o: w.own || API.ansLine(w.who), img: w.img, also: true}); draw(); setTimeout(() => finish(1), 600); } }

// —— 帮手 ——
const TONE_MK = {"ā":1,"á":2,"ǎ":3,"à":4,"ē":1,"é":2,"ě":3,"è":4,"ī":1,"í":2,"ǐ":3,"ì":4,"ō":1,"ó":2,"ǒ":3,"ò":4,"ū":1,"ú":2,"ǔ":3,"ù":4,"ǖ":1,"ǘ":2,"ǚ":3,"ǜ":4};
const toneOf = syl => { for (const ch of syl) if (TONE_MK[ch]) return TONE_MK[ch]; return 0; };
const TONE_PTS = {1: [[0, 5], [1, 5]], 2: [[0, 3], [1, 5]], 3: [[0, 2], [.45, 1], [1, 4]], 4: [[0, 5], [1, 1]], 0: [[.4, 3], [.6, 3]]};
const TONE_NM = {1: ["一声：高，平平的", "1st tone: high and flat"], 2: ["二声：往上扬，像问「啊？」", "2nd tone: rising, like asking “huh?”"], 3: ["三声：先降下去，再抬一点", "3rd tone: dip down, then up a little"], 4: ["四声：从高处一下落下来", "4th tone: drop sharply from high"], 0: ["轻声：轻轻带过", "Neutral: light and short"]};
function toneSVG(tn){ const W = 70, H = 46, y = v => H - 4 - (v - 1) * (H - 8) / 4, x = v => 6 + v * (W - 12);
  const pts = TONE_PTS[tn].map(([a, b]) => `${x(a).toFixed(1)},${y(b).toFixed(1)}`).join(" ");
  return `<svg width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">${[1, 2, 3, 4, 5].map(v => `<line x1="4" x2="${W - 4}" y1="${y(v)}" y2="${y(v)}" stroke="#eef1f6" stroke-width="1"/>`).join("")}<polyline points="${pts}" fill="none" stroke="#e2552f" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`; }
function help1(s, w){ if (!s.said) return "";
  let h = `<button class="hbtn${s.h1 ? " on" : ""}" data-act="h1">✨ ${T("练练这个词", "Practise this word")}</button>`; if (!s.h1) return h;
  h += `<div class="help"><div class="ht">${T("发音", "SOUND")}</div>`;
  if (L() === "zh"){ const sy = w.sy || [w.p], chars = [...w.t]; h += `<div class="tone" style="align-items:flex-start">` + sy.map((y, i) => { const tn = toneOf(y); return `<div style="text-align:center">${toneSVG(tn)}<div><span class="tz" data-say="${esc(chars[i] || w.t)}" data-who="" style="font-size:28px">${esc(chars[i] || w.t)}</span></div><span class="py" style="font-size:14px">${esc(y)}</span><div class="tn" style="max-width:120px">${esc(T(...TONE_NM[tn]))}</div></div>`; }).join("") + `</div>`; }
  else h += `<div class="tone"><span class="tz" data-say="${esc(w.t)}" data-who="">${esc(w.t)}</span><div><span class="py" style="font-size:14px">${esc(w.ipa || "")}</span><div class="tn">${esc(w.tip || "")}</div></div></div>`;
  MIC.h1t = {want: w.t, ok: () => gotIt($("#lv_h1t"))};
  h += `<div class="row"><button class="ear" data-act="slow" data-t="${esc(w.t)}">🐢 ${T("放慢了听", "Hear it slowly")}</button></div>${micHTML("h1t", true)}`;
  h += `<div class="ht" style="margin-top:10px">${T("带这个词的说法", "PHRASES WITH IT")}</div>` + (w.ck || []).map((c, i) => { MIC["h1c" + i] = {want: c.t, ok: () => gotIt($("#lv_h1c" + i))};
    return `<div class="ck"><span class="z" data-say="${esc(c.t)}" data-who="">${esc(c.t)}</span>${c.p ? `<span class="py">${esc(c.p)}</span>` : ""}<span class="mean">${esc(c.m)}</span><div class="row"><button class="ear" data-act="slow" data-t="${esc(c.t)}">🔊</button>${micBtn("h1c" + i)}</div><div class="live" id="lv_h1c${i}"></div></div>`; }).join("");
  return h + `</div>`; }

// —— 第二级：几个词 ——
function blocked2(seqKeys, c){ const CF = D().s2.conf || []; return seqKeys.some(k => k !== c.k && CF.some(([a, b]) => (a === k && b === c.k) || (b === k && a === c.k))); }
const enSeries = arr => { const out = []; arr.forEach(x => { if (/^but /.test(x) && out.length) out[out.length - 1] += ", " + x; else out.push(x); }); return out.length === 1 ? out[0] : out.length === 2 ? out[0] + ", and " + out[1] : out.slice(0, -1).join(", ") + ", and " + out[out.length - 1]; };
const andList = arr => arr.length > 1 ? arr.slice(0, -1).join(", ") + " and " + arr[arr.length - 1] : arr[0];
// 按卡片分组的顺序（天气 → 楼下 / 外面 → 你做了什么）排；同一组的第二张用 rc2 / tw2；after 里写了的接法（「还想睡」后面的「马上起床」= 可还是……）
function arrange(seq, f){ const cards = D().s2.cards, sorted = seq.slice().sort((a, b) => a.g - b.g || cards.indexOf(a) - cards.indexOf(b)), groups = [];
  sorted.forEach((c, i) => { const prev = sorted[i - 1], same = prev && prev.g === c.g, aft = same && c.after && c.after[prev.k];
    const piece = aft ? aft[f] : same && c[f + "2"] ? c[f + "2"] : c[f], mean = piece.m;
    let g = groups.find(x => x.g === c.g); if (!g){ g = {g: c.g, items: [], means: [], cards: []}; groups.push(g); } g.items.push(piece); g.means.push(mean); g.cards.push(c); });
  if (L() === "zh") return {t: groups.map(g => g.items.map(x => x.t).join("，")).join("，"), p: groups.map(g => g.items.map(x => x.p).join(", ")).join(", "), m: enSeries(groups.flatMap(g => g.means))};
  const gt = groups.map(g => g.cards.every(c => c.adj) && g.cards.length > 1 ? "it was " + andList(g.cards.map(c => c.adj[f === "tw" ? 1 : 0])) : g.items.map(x => x.t).join(" "));
  return {t: gt.length > 1 ? gt.slice(0, -1).join(", ") + ", and " + gt[gt.length - 1] : gt[0], p: "", m: groups.map(g => g.items.map(x => x.m).join("，")).join("，")}; }
const cap1 = x => x.replace(/^(<b>)?(.)/, (m, b, c) => (b || "") + c.toUpperCase());
function tidyLine(seq){ const a = arrange(seq, "tw"), t = D().s2.tidy || {}; return {t: fill(t.t, {X: a.t}), p: a.p ? fill(t.p, {X: a.p}) : "", m: fill(t.m, {X: a.m})}; }
function recast2(seq){ const a = arrange(seq, "rc"), r = D().s2.recast || {}; return {t: fill(r.t, {X: a.t}), p: a.p ? cap1(fill(r.p, {X: a.p})) : "", m: fill(r.m, {X: a.m})}; }
function react2(seq, d){ const c = seq.slice().sort((a, b) => b.g - a.g)[0]; return (d.react || {})[c.k]; }
function help2(s, seq, d){ if (!seq.length || s.said) return "";
  let h = `<button class="hbtn${s.h2 ? " on" : ""}" data-act="h2">✨ ${T("帮我整理成一句", "Tidy it into a sentence")}</button>`; if (!s.h2) return h;
  const tl2 = tidyLine(seq);
  MIC.h2 = {want: strip(tl2.t), ok: (heard, v) => { if (s.said) return; s.said = true; gotIt($("#lv_h2")); const o = {t: strip(tl2.t), p: tl2.p, m: tl2.m}; s.th = [{me: true, o: asHeard(o, heard), to: d.who}]; give(2, o, heard, v);
    replyIn(s.th, d.who, react2(seq, d), {}, () => finish(2)); }};
  return h + `<div class="help"><div class="ht">${T("你的词，整理成一句", "YOUR WORDS, AS A SENTENCE")}</div><div class="tidy" data-say="${esc(strip(tl2.t))}" data-who="">${tl2.t}</div>${tl2.p ? `<span class="py">${esc(tl2.p)}</span>` : ""}<span class="mean">${esc(tl2.m)}</span><div class="tn" style="font-size:11.5px;color:var(--soft);margin-top:4px">${T("红色的是你自己的词。先听一遍，再说一遍。", "The red words are yours. Listen once, then say it.")}</div>${micHTML("h2")}</div>`; }
function s2(){ const s = S[2], d = D().s2, cards = d.cards, seq = s.seq.map(k => cards.find(c => c.k === k)).filter(Boolean);
  let h = `<div class="sh">${T("几个词凑一句", "Put a few words together")}</div><div class="ssub">${T("把词卡拖进来（点一下也行），凑成一串，说出来。不用管语法，对方会懂。", "Drag cards in (or tap them), string them together, say it. Skip the grammar — " + PR(d.who).S + "'ll get it.")}</div>`;
  h += `<div id="pool">` + d.groups.map((g, gi) => `<div class="lab" style="margin-top:${gi ? 8 : 4}px">${esc(T(g[0], g[1]))}</div><div class="cards">` + cards.filter(c => c.g === gi + 1).map(c => { const off = !s.seq.includes(c.k) && blocked2(s.seq, c);
      return `<div class="wc g${c.g}${s.seq.includes(c.k) ? " used" : off ? " off" : ""}" data-c="${esc(c.k)}"><b>${esc(c.t)}</b>${c.p ? `<small>${esc(c.p)}</small>` : ""}<small>${esc(c.m)}</small></div>`; }).join("") + `</div>`).join("") + `</div>`;
  h += `<div class="lab">${T("你的一串", "Your string")}</div><div class="strip" id="strip">` + (seq.length ? seq.map((c, i) => (i ? `<span class="sep">·</span>` : "") + `<div class="wc" data-act="rm" data-k="${esc(c.k)}"><b>${esc(c.t)}</b></div>`).join("") : `<span class="ph">${T("比如：", "e.g. ")}${esc((d.ex || []).map(k => (cards.find(c => c.k === k) || {}).t).filter(Boolean).join(" · "))}</span>`) + `</div>`;
  if (seq.length && !s.said){ const line = {t: seq.map(c => c.t).join(L() === "zh" ? "，" : ", "), p: seq.map(c => c.p).filter(Boolean).join(", "), m: seq.map(c => c.m).join(L() === "zh" ? ", " : "，")};
    MIC.s2 = {want: line.t, ok: (heard, v) => { if (s.said) return; s.said = true; gotIt($("#lv_s2")); s.th = [{me: true, o: asHeard(line, heard), to: d.who}]; give(2, line, heard, v);
      replyIn(s.th, d.who, recast2(seq), {recast: true}, () => replyIn(s.th, d.who, react2(seq, d), {}, () => finish(2))); }};
    h += `<div class="say"><span class="z" data-say="${esc(line.t)}" data-who="">${esc(line.t)}</span>${line.p ? `<span class="py">${esc(line.p)}</span>` : ""}<span class="mean">${esc(line.m)}</span>${micHTML("s2")}</div>`; }
  h += help2(s, seq, d);
  if (s.th) h += `<div class="thread">${s.th.map(msgHTML).join("")}</div>`;
  if (s.said && done.has(2)) h += `<button class="again" data-act="re2">${T("再凑一串", "Make another")}</button>` + nextBtn(3);
  return h; }

// —— 第三到五级：接下来聊什么？给方向，不给句子 ——
const DIRS = [
  {k: "why", ic: "❓", ask: true, t: ["问 TA 为什么", "Ask {O} why"], s: ["挑 TA 刚说的一件事，问「为什么」。", "Pick one thing {S} just said and ask why."]},
  {k: "same", ic: "🔁", t: ["说说你那边一样还是不一样", "Same or different where you are?"], s: ["先说一样还是不一样，再说哪里不一样。", "Say same or different first, then what's different."]},
  {k: "eg", ic: "📌", t: ["讲一个你自己的例子", "Give an example from your life"], s: ["一件真的发生过的小事：什么时候、在哪儿。", "A small thing that really happened: when, where."]},
  {k: "feel", ic: "💛", t: ["说你真实的感觉", "Say how you really feel"], s: ["喜欢、受不了、羡慕、无所谓——哪个最像你？", "Love it, can't stand it, jealous, don't mind — which is you?"]},
  {k: "cur", ic: "🔍", ask: true, t: ["问一个你真的好奇的事", "Ask about something you're curious about"], s: ["TA 那边你没见过、没想明白的，直接问。", "Something on {P} side you've never seen or don't get — just ask."]}
];
const whoOf = n => n === 1 ? ((D().s1.words || []).find(x => x.k === S[1].w) || (D().s1.words || [])[0] || {}).who : n === 2 ? D().s2.who : n === 3 ? s3who() : n === 5 ? D().s5.who : (S[4].lend != null ? D().s4.lend[S[4].lend].who : D().s4.lend[0].who);
function helpTalk(n){ const s = S[n], who = whoOf(n), nm = P(who).nm;
  let h = `<button class="hbtn${s.hd ? " on" : ""}" data-act="hd" data-n="${n}">🧭 ${T("接下来聊什么？", "What to say next?")}</button>`;
  if (s.hd) h += `<div class="help"><div class="ht">${T("不知道接什么？挑一个方向", "STUCK? PICK A DIRECTION")}</div><div class="dirs">` + DIRS.map(x => { const off = x.k === "why" && !whyOK(n); return `<button class="dir${s.dir === x.k ? " on" : ""}" data-act="dir" data-n="${n}" data-k="${x.k}"${off ? ' disabled style="opacity:.45"' : ""}><span class="ic">${x.ic}</span><span><b>${esc(pron(T(...x.t), who))}</b><small>${esc(off ? pron(T("等 TA 讲完再问。", "Wait till {S}'s told you something."), who) : pron(T(...x.s), who))}</small></span></button>`; }).join("") + `</div></div>`;
  const x = DIRS.find(z => z.k === s.dir);
  if (x && s.ownBox){ MIC["ow" + n] = {ok: heard => { if (heard){ s.otxt = heard; const ta = $("#ow_" + n); if (ta) ta.value = heard; } }};
    h += `<div class="ownb" id="ob_${n}"><div class="tip">${x.ic} <b>${esc(pron(T(...x.t), who))}</b>${x.ask ? " → " + esc(nm) : ""}<br>${esc(pron(T(...x.s), who))}</div><textarea id="ow_${n}" placeholder="${esc(L() === "zh" ? T("用中文说或写，你自己的话……", "Say or write it in Chinese, your own words…") : T("用英语说或写，你自己的话……", "Say or write it in English…"))}">${esc(s.otxt || "")}</textarea>${micHTML("ow" + n, true)}<div class="row"><button class="send" data-act="osend" data-n="${n}">${T("送给 ", "Send to ")}${esc(nm)}</button></div></div>`; }
  if (s.hth && s.hth.length) h += `<div class="thread">${s.hth.map(msgHTML).join("")}</div>`;
  return h; }
function whyOK(n){ if (n === 3) return true; if (n === 4) return !!(S[4].th && S[4].th.some(m => !m.me && !m.typing)); return !!S[5].heardAll; }
function pickDir(n, k){ const s = S[n], x = DIRS.find(z => z.k === k); s.dir = k; s.ownBox = true;
  let target = null; if (k === "eg" && n === 4 && !S[4].said){ target = ".mine"; s.ownBox = false; } if (k === "eg" && n === 5 && !S[5].sent){ target = ".cells"; s.ownBox = false; }
  draw(); const el = target ? $("#stage " + target) : $("#ob_" + n);
  if (el){ el.scrollIntoView({behavior: "smooth", block: "center"}); el.classList.add("flash"); setTimeout(() => el.classList.remove("flash"), 2500); }
  if (target) toast(T(...x.s)); }
// 你自己的话：没有现成的回话，只写「TA 看到会回你」
function ownSend(n){ const s = S[n], ta = $("#ow_" + n), txt = (ta ? ta.value : s.otxt || "").trim(); if (!txt){ toast(T("先说一句或写一句", "Say or write something first")); return; }
  const who = whoOf(n); s.hth = s.hth || []; s.hth.push({me: true, o: {t: esc(txt), p: "", m: T("（你自己的话）", "(your own words)")}, to: who}); s.otxt = ""; s.ownBox = false; s.hd = false; gotIt(ta || $("#stage"));
  s.hth.push({wait: true, who}); API.said({t: txt, p: "", n, own: 1, to: who}, null); }

// —— 第三级：你来我往（用这一天现成的 re：先说你的情况 k=me，再问 TA k=ask，TA 反问 back）——
function s3who(){ const d = D().s3 || {}, R = API.re() || {}; if (d.who && R[d.who]) return d.who;
  return Object.keys(R).find(k => (R[k] || []).some(x => x.k === "ask" && x.r && x.r.back)) || Object.keys(R)[0] || ""; }
function s3opts(node){ const s = S[3], R = (API.re() || {})[s3who()] || [];
  if (node === "a") return R.filter(x => x.k === "me"); if (node === "b") return R.filter(x => x.k === "ask"); if (node === "c") return ((s.askR || {}).back) || []; return []; }
function s3(){ const s = S[3], who = s3who(); if (!who) return `<div class="ssub">${T("今天这一级还没写好。", "This step isn't ready for today yet.")}</div>`;
  const post = API.ansLine(who);
  let h = `<div class="sh">${T("你一句，我一句", "Go back and forth")}</div><div class="ssub">${T("挑一句接 TA 的话，说出来再送出。TA 会回你。", "Pick a line, say it, send it. " + pron("{S}'ll reply.", who))}</div>`;
  h += `<div class="thread">${post ? `<div class="msg them"><img class="av s" src="${face(who)}" alt=""><div style="min-width:0;flex:1"><div class="who"><b>${esc(P(who).nm)}</b> · ${esc(city(who))} · ${PASTD() ? T("回答了这一题", "answered this question") : T("回答了今天的问题", "answered today's question")}</div>${lineHTML(post, "z", who)}</div></div>` : ""}`;
  h += s.th.map(msgHTML).join("");
  const busy = s.th.length && s.th[s.th.length - 1].typing, opts = s3opts(s.node);
  if (s.node && opts.length && !busy){
    h += `<div class="ask">${s.node === "c" ? T("TA 问你了，挑一句回答 ↓", "Your turn — pick an answer ↓") : T("挑一句接上 ↓", "Pick a line ↓")}</div><div class="chips">` + opts.map((o, i) => `<button class="chip${s.pick === i ? " on" : ""}" data-act="pick3" data-i="${i}">${esc(o.t)}${o.p ? `<small>${esc(o.p)}</small>` : ""}<small>${esc(o.m)}</small></button>`).join("") + `</div>`;
    if (s.pick != null && opts[s.pick]){ const o = opts[s.pick];
      MIC.s3 = {want: o.t, ok: (heard, v) => { if (s.pick == null) return; gotIt($("#lv_s3")); const node = s.node, nx = node === "a" ? "b" : node === "b" && o.r && o.r.back && o.r.back.length ? "c" : null;
        if (node === "b") s.askR = o.r || null; s.th.push({me: true, o: asHeard(o, heard), to: who}); give(3, o, heard, v); s.pick = null; s.node = "_wait";
        replyIn(s.th, who, o.r ? {t: o.r.t, p: o.r.p, m: o.r.m, o: o.r.o, ol: o.r.ol} : null, {}, () => { s.node = nx; draw(); if (!nx) finish(3); }); }};
      h += `<div class="say" style="align-self:stretch">${lineHTML(o, "z", "")}${micHTML("s3")}</div>`; } }
  h += `</div>`;
  h += helpTalk(3);
  if (!s.node && done.has(3)) h += nextBtn(4);
  return h; }

// —— 第四级：借一句 ——
function s4(){ const s = S[4], d = D().s4, ln = s.lend != null ? d.lend[s.lend] : null, Aa = s.A != null ? d.A[s.A] : null, CL = d.clash || [];
  let h = `<div class="sh">${T("借一句大家都懂的", "Borrow what everyone says")}</div><div class="ssub">${T("先听听他们怎么说。画线的说法，点一下就借过来，放进你自己那句。", "Listen to how they say it. Tap an underlined phrase to borrow it into your own line.")}</div>`;
  h += d.lend.map((x, i) => `<div class="ans"><div class="hd"><img class="av s" src="${face(x.who)}" alt=""><div><b>${esc(P(x.who).nm)}</b><small>${esc(city(x.who))}</small></div><button class="ear pl" data-act="say4" data-i="${i}">🔊</button></div><div class="ln">${String(x.t).replace("<u>", `<u data-act="borrow" data-i="${i}" class="${s.lend === i ? "took" : ""}">`)}</div>${x.p ? `<span class="py">${esc(x.p)}</span>` : ""}<span class="mean">${esc(x.m)}</span>${x.img ? `<div class="pic" style="background-image:url('${esc(IMG(x.img))}')"></div>` : ""}</div>`).join("");
  const tpl = (ln && ln.tpl) || d.tpl, tplP = (ln && ln.tplP) || d.tplP, tplM = (ln && ln.tplM) || d.tplM;
  const slot = (v, ph) => v ? `<span class="slot fill">${esc(v)}</span>` : `<span class="slot">${ph}</span>`;
  h += `<div class="lab">${T("你的那句", "Your line")}</div><div class="mine"><div style="font:700 15px/1.9 'Noto Serif SC',Georgia,serif;color:#a4321a">` + esc(tpl).replace("{A}", slot(Aa && Aa.t, esc(d.blank ? T(d.blank.zh, d.blank.en) : T("（挑一个 ↓）", "(pick one ↓)")))).replace("{B}", slot(ln && ln.b.t, T("借来的说法", "borrowed bit"))) + `</div>`;
  h += `<div class="achips">` + d.A.map((a, i) => { const bad = ln && ln.b.tag && CL.includes(ln.b.tag) && a.tag !== ln.b.tag; return `<button class="ac${s.A === i ? " on" : ""}" data-act="A4" data-i="${i}"${bad ? " disabled" : ""}>${esc(a.t)}${a.p ? `<small>${esc(a.p)}</small>` : ""}<small>${esc(a.m)}</small></button>`; }).join("") + `</div>`;
  if (Aa && ln && !s.said){ const line = {t: cap(tpl.replace("{A}", Aa.t).replace("{B}", ln.b.t)), p: tplP ? cap(tplP.replace("{A}", Aa.p).replace("{B}", ln.b.p)) : "", m: cap(fill(tplM, {A: Aa.m, B: ln.b.m}))};
    MIC.s4 = {want: line.t, ok: (heard, v) => { if (s.said) return; s.said = true; gotIt($("#lv_s4")); s.th = [{me: true, o: asHeard(line, heard), to: ln.who}]; give(4, line, heard, v); replyIn(s.th, ln.who, ln.r, {}, () => finish(4)); }};
    h += `<div style="margin-top:6px">${lineHTML(line, "z", "")}</div>${micHTML("s4")}`; }
  h += `</div>`;
  if (s.th) h += `<div class="thread">${s.th.map(msgHTML).join("")}</div>`;
  h += helpTalk(4);
  if (s.said && done.has(4)) h += nextBtn(5);
  return h; }

// —— 第五级：讲一小段 ——
function s5line(){ const s = S[5], d = D().s5; if (s.c.some(x => x == null)) return null; const v = s.c.map((x, i) => d.cells[i][x]);
  let t = d.tpl, p = d.tplP || ""; v.forEach((o, i) => { t = t.replace(`{${i}}`, i === 1 ? cap(o.t) : o.t); p = p.replace(`{${i}}`, i === 1 ? cap(o.p) : o.p); });
  let m = d.tplM || ""; v.forEach((o, i) => { m = m.replace(`{${i}}`, i === 1 ? cap(o.m) : o.m); });
  return {t, p: p ? cap(p) : "", m, k: v[1].k}; }
function s5(){ const s = S[5], d = D().s5, st = d.story, labs = d.labs.map(x => T(x[0], x[1])), q = API.q();
  let h = `<div class="sh">${T("讲一小段自己的事", "Tell a little story")}</div>`;
  h += `<div class="qbox"><img class="av s" src="${face(q.by)}" alt=""><div>${lineHTML(q, "q", q.by)}</div></div>`;
  if (!s.sent){
    h += `<div class="ssub">${T("讲一小段：三格提示，每格挑一个——说出来，或者写下来。", "Tell a little story: pick one in each box — say it, or write it.")}</div><div class="cells">` + d.cells.map((opts, ci) => `<div class="cell"><div class="cl">${ci + 1} · ${esc(labs[ci])}</div><div class="opts">` + opts.map((o, i) => `<button class="ac${s.c[ci] === i ? " on" : ""}" data-act="c5" data-ci="${ci}" data-i="${i}">${esc(o.t)}${o.p ? `<small>${esc(o.p)}</small>` : ""}<small>${esc(o.m)}</small></button>`).join("") + `</div></div>`).join("") + `</div>`;
    const line = s5line();
    if (line){
      const send = (heard, v) => { if (s.sent) return; s.sent = true; const own = s.write && s.txt && s.txt.trim() && s.txt.trim() !== line.t;
        const mine = own ? {t: esc(s.txt.trim()), p: "", m: T("（你自己写的）", "(your own words)")} : asHeard(line, heard); gotIt($("#lv_s5") || $("#stage"));
        s.th = [{me: true, o: mine, to: d.who}]; give(5, own ? {t: s.txt.trim(), p: ""} : line, own ? null : heard, v);
        if (own){ s.th.push({wait: true, who: d.who}); s.story = true; draw(); }
        else replyIn(s.th, d.who, (d.react || {})[line.k], {}, () => replyIn(s.th, d.who, d.bridge, {}, () => { s.story = true; draw(); })); };
      MIC.s5 = {want: line.t, ok: send}; s._send = send;
      h += `<div class="say">` + (s.write ? `<div class="wr"><textarea id="ta5">${esc(s.txt != null ? s.txt : line.t)}</textarea></div><div class="row"><button class="send" data-act="send5">${T("送出", "Send")}</button><button class="said" data-act="mode5">${T("改成说", "Say it instead")}</button></div>`
        : `${lineHTML(line, "z", "")}${micHTML("s5")}<button class="said" data-act="mode5">✍️ ${T("我想写下来", "I'd rather write it")}</button>`) + `</div>`; } }
  if (s.th.length) h += `<div class="thread">${s.th.map(msgHTML).join("")}</div>`;
  if (s.story && st){ const pct = s.pl == null ? 0 : Math.round((s.pl + 1) / st.lines.length * 100), nm = P(st.who).nm;
    h += `<div class="story">${st.img ? `<div class="pic" style="background-image:url('${esc(IMG(st.img))}')"><span class="city">${esc(nm)} · ${esc(city(st.who))}</span></div>` : ""}`;
    h += `<button class="play" data-act="play5"><span class="ic">${s.playing ? "❚❚" : "▶"}</span>${s.heardAll ? T("再听一遍", "Listen again") : (d.btn ? T(d.btn.zh, d.btn.en) : T("听 {nm} 讲一小段", "Hear a short story from {nm}")).replace(/\{nm\}/g, nm)}</button><div class="prog"><i style="width:${pct}%"></i></div>`;
    h += `<button class="said" data-act="tx5" style="margin-top:6px">${s.tx ? T("收起文字", "Hide the words") : T("看文字", "Show the words")}</button>`;
    if (s.tx) h += `<div class="tx">` + st.lines.map((o, i) => `<p class="${s.pl === i ? "now" : ""}">${lineHTML(o, "z", st.who)}</p>`).join("") + `</div>`;
    if (s.heardAll){
      h += `<div class="qq"><div class="qt">${esc(st.q.t)}</div>${st.q.p ? `<span class="py">${esc(st.q.p)}</span>` : ""}<span class="mean">${esc(st.q.m)}</span>` + st.opts.map((o, i) => `<button class="qo${s.q === i ? (o.ok ? " ok" : " soft") : ""}" data-act="q5" data-i="${i}"${s.qok ? " disabled" : ""}>${esc(o.t)}${o.p ? `<small>${esc(o.p)}</small>` : ""}<small>${esc(o.m)}</small></button>`).join("");
      if (s.q != null && !st.opts[s.q].ok) h += `<button class="nudge" data-act="rekey">🔊 ${T("再听一遍那一句", "Hear that bit again")}</button>`;
      h += `</div>`; }
    if (s.th2) h += `<div class="thread">${s.th2.map(msgHTML).join("")}</div>`;
    h += `</div>`; }
  h += helpTalk(5);
  if (done.has(5) && s.qok) h += `<button class="again" data-act="re5">${T("换一种说法再讲一次", "Tell it another way")}</button>`;
  return h; }
function play5(){ const s = S[5], st = D().s5.story; if (s.playing){ s.playing = false; hush(); draw(); return; }
  s.playing = true; let i = 0; const go = () => { if (!s.playing || !HOST || !HOST.isConnected) return; if (i >= st.lines.length){ s.playing = false; s.heardAll = true; draw(); return; } s.pl = i; draw(); say(st.lines[i].t, st.who, () => { i++; setTimeout(go, 250); }); }; go(); }

function nextBtn(n){ return `<button class="next" data-act="step" data-n="${n}">${T("再往上一级", "Up one step")} → ${esc(T(...STEPS[n - 1]))}</button>`; }
function draw(){ if (!SR || !HOST || !HOST.isConnected) return; const st = $("#stage"); if (!st) return; st.innerHTML = `<div class="stage">${[s1, s2, s3, s4, s5][cur - 1]()}${cur < 3 && S[cur].hth && S[cur].hth.length ? `<div class="thread">${S[cur].hth.map(msgHTML).join("")}</div>` : ""}</div>`; }
function scrollDown(){ setTimeout(() => { const st = $("#stage"); if (st) { const r = st.getBoundingClientRect(); if (r.bottom > innerHeight) st.lastElementChild && st.lastElementChild.scrollIntoView({behavior: "smooth", block: "end"}); } }, 80); }

// —— 点击 ——
function onClick(e){
  const sv = e.target.closest("[data-say]"); if (sv && !e.target.closest("[data-act]")){ say(sv.dataset.say, sv.dataset.who || null, null, sv.dataset.lang || null); flt(sv, "♪"); return; }
  const b = e.target.closest("[data-act]"); if (!b || b.disabled) return; const a = b.dataset.act, i = +b.dataset.i;
  press(b); blip(880); flt(b);
  if (a === "cam"){ S[1].ph = "own"; API.pickPhoto(); return; }
  if (a === "h1"){ S[1].h1 = !S[1].h1; draw(); if (S[1].h1) scrollDown(); return; }
  if (a === "slow"){ try { hush(); const u = new SpeechSynthesisUtterance(b.dataset.t); u.lang = BCP(); u.rate = .5; const v = voiceFor(u.lang); if (v) u.voice = v; speechSynthesis.speak(u); } catch(e2){} return; }
  if (a === "h2"){ S[2].h2 = !S[2].h2; draw(); if (S[2].h2){ scrollDown(); const t = tidyLine(S[2].seq.map(k => D().s2.cards.find(c => c.k === k))); say(strip(t.t), null); } return; }
  if (a === "hd"){ const n = +b.dataset.n; S[n].hd = !S[n].hd; draw(); return; }
  if (a === "dir"){ pickDir(+b.dataset.n, b.dataset.k); return; }
  if (a === "osend"){ ownSend(+b.dataset.n); return; }
  if (a === "step"){ hush(); cur = +b.dataset.n; API.step(cur); drawStairs(); draw(); HOST.scrollIntoView({behavior: "smooth", block: "start"}); return; }
  if (a === "ph"){ S[1].ph = b.dataset.k; draw(); return; }
  if (a === "w"){ const s = S[1]; if (s.dest) return; if (s.said){ s.said = false; s.th = null; API.unsaid(); } s.w = b.dataset.k; const w = D().s1.words.find(x => x.k === s.w); draw(); say(w.t, null); scrollDown(); return; }
  if (a === "ear"){ const el = b.closest(".say, .mine") && b.closest(".say, .mine").querySelector(".z"); if (el) say(el.dataset.say, null); return; }
  if (a === "said"){ saidBtn(b.dataset.id); return; }
  if (a === "type"){ typeBox(b.dataset.id); return; }
  if (a === "typesend"){ typeSend(b.dataset.id); return; }
  if (a === "rm"){ if (S[2].said) return; S[2].seq = S[2].seq.filter(k => k !== b.dataset.k); draw(); return; }
  if (a === "re2"){ S[2] = {seq: []}; draw(); return; }
  if (a === "pick3"){ S[3].pick = i; const o = s3opts(S[3].node)[i]; draw(); if (o) say(o.t, null); scrollDown(); return; }
  if (a === "say4"){ const x = D().s4.lend[i]; say(x.t, x.who); return; }
  if (a === "borrow"){ const s = S[4], d = D().s4, x = d.lend[i]; if (s.said) return; s.lend = i;
    if (x.b.tag && (d.clash || []).includes(x.b.tag)){ const k = d.A.findIndex(z => z.tag === x.b.tag); if (s.A == null || d.A[s.A].tag !== x.b.tag) s.A = k < 0 ? null : k; }
    toast(T(`借来了：${P(x.who).nm} 的说法`, `Borrowed from ${P(x.who).nm}`)); blip(1320); draw(); say(x.b.t, x.who); return; }
  if (a === "A4"){ const s = S[4]; if (s.said) return; s.A = i; draw(); return; }
  if (a === "c5"){ const s = S[5]; s.c[+b.dataset.ci] = i; s.txt = null; draw(); if (s.c.every(x => x != null)) scrollDown(); return; }
  if (a === "mode5"){ S[5].write = !S[5].write; draw(); return; }
  if (a === "send5"){ const s = S[5], ta = $("#ta5"); s.txt = ta ? ta.value : ""; s._send && s._send(null, null); return; }
  if (a === "play5"){ play5(); return; }
  if (a === "rekey"){ const st = D().s5.story; say(st.lines[st.key].t, st.who, () => {}); return; }
  if (a === "tx5"){ S[5].tx = !S[5].tx; draw(); return; }
  if (a === "q5"){ const s = S[5], st = D().s5.story, o = st.opts[i]; s.q = i;
    if (o.ok){ s.qok = true; draw(); gotIt(b); s.th2 = []; replyIn(s.th2, st.who, st.yes, {}, () => finish(5)); }
    else { draw(); say(st.lines[st.key].t, st.who); } return; }
  if (a === "re5"){ S[5] = {c: [null, null, null], th: [], q: null}; draw(); return; }
}
// 第二级：拖词卡（点一下也算放进去）
let drag = null;
function addCard(k){ const s = S[2], cc = D().s2.cards.find(x => x.k === k); if (!cc || s.said) return;
  if (blocked2(s.seq, cc)){ toast(T("这张跟你放的另一张对不上", "That one clashes with a card you picked")); return; }
  if (!s.seq.includes(k) && s.seq.length < 6){ s.seq.push(k); blip(1046); say(cc.t, null); draw(); flt($("#strip"), "+"); } }
function wire(){
  SR.addEventListener("click", onClick);
  SR.addEventListener("input", e => { const m = e.target.id && e.target.id.match(/^ow_(\d)$/); if (m) S[+m[1]].otxt = e.target.value; });
  SR.addEventListener("pointerdown", e => { const m = e.target.closest("[data-mic]"); if (m){ e.preventDefault(); press(m); if (recId){ micStop(); return; } t0 = Date.now(); HOLD = false; micStart(m.dataset.mic); setTimeout(() => { if (recId && Date.now() - t0 >= 440) HOLD = true; }, 450); return; }
    const c = e.target.closest("#pool .wc"); if (c) drag = {k: c.dataset.c, x: e.clientX, y: e.clientY, el: c, g: null}; });
  SR.addEventListener("pointerup", e => { if (recId && HOLD && e.target.closest("[data-mic]")){ HOLD = false; micStop(); } });
}
document.addEventListener("pointermove", e => { if (!drag) return; if (!drag.g && Math.hypot(e.clientX - drag.x, e.clientY - drag.y) > 6){ drag.g = drag.el.cloneNode(true); drag.g.classList.add("ghost"); SR.appendChild(drag.g); }
  if (drag.g){ drag.g.style.left = e.clientX + "px"; drag.g.style.top = e.clientY + "px"; const st = $("#strip"); if (st){ const r = st.getBoundingClientRect(); st.classList.toggle("over", e.clientX > r.left && e.clientX < r.right && e.clientY > r.top && e.clientY < r.bottom); } } });
document.addEventListener("pointerup", e => { if (!drag) return; const d = drag; drag = null; let add = !d.g; const st = $("#strip");
  if (d.g){ if (st){ const r = st.getBoundingClientRect(); add = e.clientX > r.left && e.clientX < r.right && e.clientY > r.top && e.clientY < r.bottom; st.classList.remove("over"); } d.g.remove(); }
  if (add) addCard(d.k); });

