// mount：howabout 每画一次第 2 屏，就把这块（一直是同一个元素，进度都在）放回占位的地方
function mount(ph, api){ API = api; if (!ph) return; const key = api.key();
  if (key !== KEY){ KEY = key; fresh(); NOSR = false; const v = +api.step() || 0; LAST = v >= 1 && v <= 5 ? v : 0; cur = LAST || 1; }
  if (!HOST){ HOST = document.createElement("div"); HOST.className = "ha-fsh"; HOST.dataset.nopy = ""; SR = HOST.attachShadow({mode: "open"}); SR.innerHTML = `<style>${CSS}</style><div class="stwrap"><div class="stairs" id="stairs"></div><div class="sthint" id="sthint"></div></div><div id="stage"></div>`; wire(); }
  ph.replaceWith(HOST); drawStairs(); draw(); }
