// 学中文的一句：Z("一杯 yì bēi|热 rè|拿铁 nátiě|。", 意思)；学英语的一句：E("A hot latte, [less sugar].", 中文意思)
const Z = (s, m, yi) => { const t = [], p = []; s.split("|").forEach(x => { x = x.trim(); const g = x.match(/^(\S+)\s+(.+)$/); if (g && !PUN.test(g[1])){ t.push(g[1]); p.push(g[2]); } else { t.push(x); p.push(""); } }); return {t: t.join("|"), p: p.join("|"), m, yi}; };
const E = (t, m) => ({t, m});
