// ── 录音只存在手机上（IndexedDB hv.actw / rec，键 = 活动|那一句）──
let DBP = null;
const db = () => DBP || (DBP = new Promise(ok => { try { const r = indexedDB.open("hv.actw", 1); r.onupgradeneeded = () => r.result.createObjectStore("rec"); r.onsuccess = () => ok(r.result); r.onerror = () => ok(null); } catch(e){ ok(null); } }));
const recPut = async (k, v) => { const d = await db(); if (!d) return; try { d.transaction("rec", "readwrite").objectStore("rec").put(v, k); } catch(e){} };
const recGet = async k => { const d = await db(); if (!d) return null; return new Promise(ok => { try { const q = d.transaction("rec").objectStore("rec").get(k); q.onsuccess = () => ok(q.result || null); q.onerror = () => ok(null); } catch(e){ ok(null); } }); };
const SRok = () => !!(window.SpeechRecognition || window.webkitSpeechRecognition) && !navigator.brave;
