 function confetti(n){ const cs = ["#e2552f", "#ffd27a", "#2f7d70", "#14305c", "#e8b44a"]; for (let k = 0; k < (n || 40); k++){ const c = document.createElement("i"); c.className = "cf"; c.style.left = Math.random() * 100 + "%"; c.style.background = cs[k % cs.length]; c.style.animationDelay = Math.random() * .5 + "s"; c.style.borderRadius = k % 3 ? "2px" : "50%"; RT.appendChild(c); setTimeout(() => c.remove(), 2900); } }
