 function toApp(sel){ setTimeout(() => { const el = typeof sel === "string" ? RS.querySelector(sel) : sel; if (el) el.scrollIntoView({behavior: "smooth", block: "center"}); }, 80); }
 // 第几天是哪一天：随到随开 = 你加入那天 + i（还没加入就按今天算）
